        <p class="parrafo">{{ mb_strtoupper($representante['nombre']) }}, IDENTIFICADO CON DNI N.° {{ $representante['dni'] }}, CON DOMICILIO EN {{ mb_strtoupper($representante['domicilio']) }}.</p>
